import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../app/providers.dart';
class StudentHomeScreen extends ConsumerWidget {const StudentHomeScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final user=ref.watch(currentUserProvider);return Scaffold(appBar:AppBar(title:Text('مرحباً، ${user.valueOrNull?.name ?? ''}'),actions:[IconButton(onPressed:()=>ref.read(authRepositoryProvider).signOut(),icon:const Icon(Icons.logout))]),body:user.when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('تعذر تحميل ملفك: $e')),data:(profile)=>ListView(padding:const EdgeInsets.all(20),children:[Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('رحلتك التعليمية',style:TextStyle(fontWeight:FontWeight.bold,fontSize:18)),const SizedBox(height:12),const LinearProgressIndicator(value:.25),const SizedBox(height:8),const Text('أكمل ملفك الأكاديمي والمهارات للحصول على توصيات أدق.')]))),const SizedBox(height:18),Wrap(spacing:10,runSpacing:10,children:[('استكشف التخصصات','/majors',Icons.account_tree),('المحادثات','/chat',Icons.forum),('التقييمات','/assessments',Icons.quiz),('المواعيد','/appointments',Icons.calendar_month)].map((item)=>ActionChip(avatar:Icon(item.$3),label:Text(item.$1),onPressed:()=>Navigator.pushNamed(context,item.$2))).toList()),const SizedBox(height:24),Text('التخصصات المتاحة',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:8),ref.watch(majorsProvider).when(loading:()=>const LinearProgressIndicator(),error:(e,_)=>Text('تعذر تحميل التخصصات: $e'),data:(majors)=>Column(children:majors.take(3).map((m)=>Card(child:ListTile(title:Text(m.name),subtitle:Text(m.categoryId),onTap:()=>Navigator.pushNamed(context,'/majors')))).toList()))]));}}
